19	// recallRetrievalEngine is emitted with recall --json. Semantic retrieval was
20	// removed (trail #278: BM25 matched or beat the embedder stack end-to-end);
21	// the semantic/vector fields are retained in the schema and report inert
22	// values so existing consumers keep parsing.
23	type recallRetrievalEngine struct {
24		SchemaVersion         int    `json:"schema_version"`
25		EffectiveEngine       string `json:"effective_engine,omitempty"`
26		IdentityVerified      bool   `json:"identity_verified"`
27		SemanticRequested     bool   `json:"semantic_requested"`
28		SemanticApplied       bool   `json:"semantic_applied"`
29		SemanticAvailable     bool   `json:"semantic_available"`
30		BM25Enabled           bool   `json:"bm25_enabled"`
31		BM25Applied           bool   `json:"bm25_applied"`
32		FallbackUsed          bool   `json:"fallback_used"`
33		IdentityFailureReason string `json:"identity_failure_reason,omitempty"`
34	}
