36	func recallRetrievalIdentity() recallRetrievalEngine {
37		return recallRetrievalEngine{
38			SchemaVersion:    1,
39			EffectiveEngine:  recallEngineBM25Lexical,
40			IdentityVerified: true,
41			BM25Enabled:      true,
42			BM25Applied:      true,
43		}
44	}
