76	func newRecallCommand(opts Options) *cobra.Command {
77		var evidence bool
78		var evidenceBytes int
79		var (
80			branch                string
81			limit                 int
82			includeAll            bool
83			scope                 string
84			kind                  string
85			locus                 string
86			noSemantic            bool
87			expand                bool
88			agent                 string
89			model                 string
90			agentCommand          []string
91			jsonOut               bool
92			eligibleBefore        string
93			sessionDatesPath      string
94			excludeSessionIDs     []string
95			readOnlySemanticCache bool
96			noGlobal              bool
97		)
98		cmd := &cobra.Command{
99			Use:   "recall <query>",
100			Short: "Retrieve durable memories matching a query for the current branch",
101			Args:  cobra.MaximumNArgs(1),
102			RunE: func(cmd *cobra.Command, args []string) error {
103				query := ""
104				if len(args) == 1 {
105					query = args[0]
106				}
107				if evidence {
108					for _, flag := range []string{"all", "scope", "kind", "locus", "expand", "agent", "model", "agent-command", "eligible-before", "session-dates", "exclude-session-id", "read-only-semantic-cache"} {
109						if cmd.Flags().Changed(flag) {
110							return fmt.Errorf("--%s is not supported with --evidence; evidence recall is deterministic and does not apply memory filters", flag)
111						}
112					}
113				} else if cmd.Flags().Changed("evidence-bytes") {
114					return fmt.Errorf("--evidence-bytes requires --evidence")
115				}
116				if err := validateScopeFlag(scope); err != nil {
117					return err
118				}
119				if err := factstore.ValidateKindFlag(kind); err != nil {
120					return err
121				}
122				repoDir, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
123				if err != nil {
124					return err
125				}
126				if evidence {
127					return runRecallEvidence(cmd, brainDir, resolvedBranch, query, limit, evidenceBytes, jsonOut)
128				}
129				allFacts, err := factstore.Load(brainDir, resolvedBranch)
130				if err != nil {
131					return err
132				}
133				// Facts that are not about this repository — preferences, team
134				// conventions, environment details — merge in here, so something
135				// recorded once applies everywhere. They go through every filter
136				// and the same ranking as repository facts; the only difference is
137				// that they are labelled, because acting on a global convention as
138				// though this repo had declared it is a different thing.
139				globalIDs := map[string]bool{}
140				if globalFactsEnabled(noGlobal) {
141					globalFacts, globalErr := factstore.LoadGlobal(opts.Env)
142					if globalErr != nil {
143						// A damaged global store must not take recall down with it;
144						// the repository's own facts are the answer to most queries.
145						fmt.Fprintf(cmd.ErrOrStderr(), "warning: global memories unavailable: %v\n", globalErr)
146					} else {
147						allFacts, globalIDs = retrieval.MergeGlobalFacts(allFacts, globalFacts)
148					}
149				}
150				var storeWarning string
151				manifest, manifestErr := bmanifest.Load(brainDir)
152				if manifestErr != nil {
153					storeWarning = "memory source manifest unavailable: " + manifestErr.Error()
154				} else if manifest != nil && manifest.Sources != nil {
155					storeWarning = factstore.MissingStoreWarningForBranch(brainDir, manifest.Sources.Facts, resolvedBranch)
156				}
157				candidateFacts := allFacts
158				var eligibility *factEligibilityAudit
159				if eligibleBefore != "" || sessionDatesPath != "" || len(excludeSessionIDs) > 0 {
160					if eligibleBefore == "" || sessionDatesPath == "" {
161						return fmt.Errorf("--eligible-before and --session-dates must be supplied together")
162					}
163					dates, loadErr := loadSessionDates(sessionDatesPath)
164					if loadErr != nil {
165						return loadErr
166					}
167					filtered, audit, filterErr := filterFactsByTemporalEligibility(allFacts, dates, eligibleBefore, excludeSessionIDs)
168					if filterErr != nil {
169						return filterErr
170					}
171					candidateFacts = filtered
172					eligibility = &audit
173				}
174				facts := factstore.FilterByLocus(factstore.FilterByKind(factstore.FilterByScope(candidateFacts, scope), kind), locus)
175				effectiveQuery := query
176				if expand && strings.TrimSpace(query) != "" {
177					resolved := agent
178					if resolved == "auto" {
179						resolved = defaultRefreshAgent(cmd.Context(), opts.Runner, repoDir)
180					}
181					expandArgs, expErr := base.DistillAgentCommandArgs(resolved, agentCommand, queryExpansionPrompt())
182					if expErr != nil {
183						return fmt.Errorf("expand agent: %w", expErr)
184					}
185					expandArgs = base.InjectAgentModel(expandArgs, resolved, model)
186					exp, expErr := expandQuery(cmd.Context(), defaultDistillAgentRunner(resolved), expandArgs, repoDir, query, loadExpansionCache(""))
187					if expErr != nil {
188						return fmt.Errorf("expand query: %w", expErr)
189					}
190					effectiveQuery = expandedQuery(query, exp)
191				}
192				// --no-semantic and --read-only-semantic-cache are vacuously
193				// satisfied since the semantic arm was removed (trail #278):
194				// ranking is always lexical and no vector cache exists to write.
195				_, _ = noSemantic, readOnlySemanticCache
196				matches := rankFacts(facts, effectiveQuery, limit, includeAll)
197				// Locus drift (Phase 2 item 4): flag surfaced facts whose code
198				// locus left the worktree, so the agent knows which to re-verify.
199				drift := retrieval.FactsLocusDrift(repoDir, retrieval.FactsEligibleForLocusDrift(matches, globalIDs))
200				// Live trust state: a surfaced fact with a pending merge/supersede
201				// proposal is annotated (not collapsed — recall keeps its record
202				// shape), matching the guard the unified query/search/get path
203				// applies. Groups are built from the unfiltered branch set so
204				// scope/kind/locus filters cannot hide a pending relationship.
205				// Nothing surfaced means no annotation and no queue warning, so skip
206				// the proposal read entirely on the empty-recall path.
207				var proposals []factProposal
208				var proposalsErr error
209				var pendingReviews map[string]factReviewNotice
210				if len(matches) > 0 {
211					proposals, proposalsErr = loadFactProposals(brainDir, resolvedBranch)
212					if proposalsErr == nil {
213						localFacts := retrieval.FactsEligibleForLocusDrift(allFacts, globalIDs)
214						pendingReviews = retrieval.FactsPendingReview(localFacts, proposals, matches)
215					}
216				}
217				recordReceipt := func() {
218					recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, "recall",
219						vitalityHead(cmd.Context(), opts.Runner, repoDir), query, factRecordIDs(matches))
220				}
221				if jsonOut {
222					// Recall's JSON envelope is fact-centric (top-level `facts`), so
223					// its fact-scoped keys stay unprefixed: `pending_reviews` and
224					// `locus_drift`. The brief report is a multi-domain object and
225					// prefixes the same concepts as `facts_pending_review` /
226					// `facts_locus_drift` to disambiguate. This per-surface split is
227					// intentional and kept as-is; we do not unify the keys.
228					out := map[string]any{"branch": resolvedBranch, "query": query, "facts": matches}
229					// A consumer that renders these has to be able to tell which
230					// facts came from outside this repository; the ids are the
231					// smallest way to say so without changing the fact shape that
232					// every existing reader binds to.
233					if ids := sortedGlobalFactIDs(matches, globalIDs); len(ids) > 0 {
234						out["global_fact_ids"] = ids
235					}
236					engine := recallRetrievalIdentity()
237					out["retrieval_engine"] = engine
238					if engine.EffectiveEngine != "" {
239						out["effective_engine"] = engine.EffectiveEngine
240					}
241					if eligibility != nil {
242						eligibility.DeliveredCount = len(matches)
243						out["eligibility"] = eligibility
244					}
245					if len(drift) > 0 {
246						out["locus_drift"] = drift
247					}
248					if len(pendingReviews) > 0 {
249						out["pending_reviews"] = pendingReviews
250					}
251					if proposalsErr != nil && len(matches) > 0 {
252						out["warnings"] = []string{retrieval.FactReviewQueueUnavailableWarning}
253					}
254					if storeWarning != "" {
255						warnings, _ := out["warnings"].([]string)
256						out["warnings"] = append(warnings, storeWarning)
257					}
258					if len(matches) == 0 {
259						if note := emptyResultBlindSpotOnBranch(brainDir, resolvedBranch); note != "" && storeWarning == "" {
260							out["blind_spot"] = note
261						}
262					}
263					if err := cmdutil.WriteJSON(cmd, out); err != nil {
264						return err
265					}
266					if len(matches) > 0 {
267						recordReceipt()
268					}
269					return nil
270				}
271				if len(matches) == 0 {
272					return cmdutil.WriteText(cmd, func(out io.Writer) {
273						fmt.Fprintf(out, "no memories for %q on %s\n", query, resolvedBranch)
274						if storeWarning != "" {
275							fmt.Fprintln(out, "warning: "+storeWarning)
276						}
277						if note := emptyResultBlindSpotOnBranch(brainDir, resolvedBranch); note != "" && storeWarning == "" {
278							fmt.Fprintln(out, note)
279						}
280					})
281				}
282				if err := cmdutil.WriteText(cmd, func(out io.Writer) {
283					if storeWarning != "" {
284						fmt.Fprintln(out, "warning: "+storeWarning)
285					}
286					if proposalsErr != nil {
287						fmt.Fprintf(out, "⚠ %s\n", retrieval.FactReviewQueueUnavailableWarning)
288					}
289					for _, f := range matches {
290						if globalIDs[f.ID] {
291							// Without this a global convention is indistinguishable
292							// from something this repository declared, and an agent
293							// would cite it as a property of the codebase.
294							printGlobalFactLine(out, f)
295						} else {
296							printFactLine(out, f)
297						}
298						if gone := drift[f.ID]; len(gone) > 0 {
299							fmt.Fprintf(out, "  ⚠ stale locus (no longer in worktree): %s\n", strings.Join(gone, ", "))
300						}
301						if notice, ok := pendingReviews[f.ID]; ok {
302							fmt.Fprintf(out, "  %s\n", retrieval.FactReviewNoticeLine(notice))
303						}
304					}
305				}); err != nil {
306					return err
307				}
308				recordReceipt()
309				return nil
310			},
311		}
