389	// printGlobalFactLine renders a fact that came from the global store rather than
390	// this repository.
391	func printGlobalFactLine(out io.Writer, f factRecord) {
392		marker := ""
393		switch f.Status {
394		case factStatusSuperseded:
395			marker = " (superseded)"
396		case factStatusRetracted:
397			marker = " (retracted)"
398		}
399		fmt.Fprintf(out, "%s %s [%s] (global)%s\n  %s\n", f.ID, factstore.KindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
400	}
