402	// sortedGlobalFactIDs returns the ids of the surfaced facts that are global, in
403	// the order they were surfaced, so JSON output is stable across runs.
404	func sortedGlobalFactIDs(matches []factRecord, globalIDs map[string]bool) []string {
405		var ids []string
406		for _, f := range matches {
407			if globalIDs[f.ID] {
408				ids = append(ids, f.ID)
409			}
410		}
411		return ids
412	}
