414	// printFactLine renders a fact for human-readable listings.
415	func printFactLine(out io.Writer, f factRecord) {
416		marker := ""
417		switch f.Status {
418		case factStatusSuperseded:
419			marker = " (superseded)"
420		case factStatusRetracted:
421			marker = " (retracted)"
422		}
423		fmt.Fprintf(out, "%s %s [%s]%s\n  %s\n", f.ID, factstore.KindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
424	}
