46	// resolveFactsTarget resolves the repo, brain directory, and the branch facts
47	// are scoped to (the live git branch unless overridden). It is shared by the
48	// fact read/write commands.
49	func resolveFactsTarget(ctx context.Context, opts Options, target, branchOverride string) (repoDir, brainDir, branch string, err error) {
50		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
51		if err != nil {
52			return "", "", "", err
53		}
54		if !local {
55			return "", "", "", fmt.Errorf("memories require a local repository path: %s", target)
56		}
57		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
58		if err != nil {
59			return "", "", "", err
60		}
61		branch = strings.TrimSpace(branchOverride)
62		if branch == "" {
63			if current, gitErr := base.GitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
64				branch = strings.TrimSpace(current)
65			}
66		}
67		if branch == "" {
68			branch = distillDefaultBranch
69		}
70		return repoDir, storage.BrainDir, branch, nil
71	}
