1	package cli
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"strings"
8		"time"
9	)
10	
11	const (
12		eligibilityEmptyProvenance = "empty_provenance"
13		eligibilityExcludedSession = "excluded_session"
14		eligibilityUnknownSession  = "unknown_session"
15		eligibilityAtOrAfterCutoff = "at_or_after_cutoff"
16	)
17	
18	// factEligibilityAudit records the complete candidate accounting before ranking.
19	// DeliveredCount is filled by recall after the eligible corpus has been ranked.
20	type factEligibilityAudit struct {
21		PrefilterCorpusCount int            `json:"prefilter_corpus_count"`
22		EligibleCount        int            `json:"eligible_count"`
23		ExcludedCounts       map[string]int `json:"excluded_counts"`
24		DeliveredCount       int            `json:"delivered_count"`
25	}
26	
27	func loadSessionDates(path string) (map[string]string, error) {
28		raw, err := os.ReadFile(path)
29		if err != nil {
30			return nil, fmt.Errorf("read session dates: %w", err)
31		}
32		var dates map[string]string
33		if err := json.Unmarshal(raw, &dates); err != nil {
34			return nil, fmt.Errorf("parse session dates: %w", err)
35		}
36		if dates == nil {
37			return nil, fmt.Errorf("parse session dates: expected a JSON object")
38		}
39		return dates, nil
40	}
41	
42	func parseEligibilityTime(value string) (time.Time, error) {
43		value = strings.TrimSpace(value)
44		if strings.HasSuffix(value, "z") {
45			value = strings.TrimSuffix(value, "z") + "Z"
46		}
47		if parsed, err := time.Parse(time.RFC3339Nano, value); err == nil {
48			return parsed, nil
49		}
50		// Match the harness's established compatibility behavior: a timestamp with
51		// no explicit offset is UTC, never local machine time.
52		if parsed, err := time.ParseInLocation("2006-01-02T15:04:05.999999999", value, time.UTC); err == nil {
53			return parsed, nil
54		}
55		return time.Time{}, fmt.Errorf("invalid RFC3339 timestamp %q", value)
56	}
57	
58	// filterFactsByTemporalEligibility constructs the complete task-scoped candidate
59	// set before lexical or semantic ranking. Every provenance anchor must identify a
60	// known, non-excluded session strictly before cutoff; uncertainty fails closed.
61	func filterFactsByTemporalEligibility(
62		facts []factRecord,
63		sessionDates map[string]string,
64		cutoffValue string,
65		excludeSessionIDs []string,
66	) ([]factRecord, factEligibilityAudit, error) {
67		cutoff, err := parseEligibilityTime(cutoffValue)
68		if err != nil {
69			return nil, factEligibilityAudit{}, fmt.Errorf("--eligible-before: %w", err)
70		}
71		excluded := make(map[string]struct{}, len(excludeSessionIDs))
72		for _, id := range excludeSessionIDs {
73			if id = strings.TrimSpace(id); id != "" {
74				excluded[id] = struct{}{}
75			}
76		}
77		audit := factEligibilityAudit{
78			PrefilterCorpusCount: len(facts),
79			ExcludedCounts: map[string]int{
80				eligibilityEmptyProvenance: 0,
81				eligibilityExcludedSession: 0,
82				eligibilityUnknownSession:  0,
83				eligibilityAtOrAfterCutoff: 0,
84			},
85		}
86		eligible := make([]factRecord, 0, len(facts))
87		for _, fact := range facts {
88			if len(fact.Provenance) == 0 {
89				audit.ExcludedCounts[eligibilityEmptyProvenance]++
90				continue
91			}
92			hasEmptyAnchor := false
93			hasExcludedSession := false
94			hasUnknownSession := false
95			hasAtOrAfterCutoff := false
96			for _, anchor := range fact.Provenance {
97				sessionID := strings.TrimSpace(anchor.SessionID)
98				if sessionID == "" {
99					hasEmptyAnchor = true
100					continue
101				}
102				if _, found := excluded[sessionID]; found {
103					hasExcludedSession = true
104					continue
105				}
106				createdValue, found := sessionDates[sessionID]
107				if !found {
108					hasUnknownSession = true
109					continue
110				}
111				created, parseErr := parseEligibilityTime(createdValue)
112				if parseErr != nil {
113					hasUnknownSession = true
114					continue
115				}
116				if !created.Before(cutoff) {
117					hasAtOrAfterCutoff = true
118				}
119			}
120			// Assign exactly one deterministic reason, independent of provenance
121			// anchor order, while retaining the strictest fail-closed precedence.
122			reason := ""
123			switch {
124			case hasEmptyAnchor:
125				reason = eligibilityEmptyProvenance
126			case hasExcludedSession:
127				reason = eligibilityExcludedSession
128			case hasUnknownSession:
129				reason = eligibilityUnknownSession
130			case hasAtOrAfterCutoff:
131				reason = eligibilityAtOrAfterCutoff
132			}
133			if reason != "" {
134				audit.ExcludedCounts[reason]++
135				continue
136			}
137			eligible = append(eligible, fact)
138		}
139		audit.EligibleCount = len(eligible)
140		return eligible, audit, nil
141	}
