1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"os"
7		"strings"
8	
9		"github.com/entireio/entire-brain/internal/cli/internal/base"
10		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
11	)
12	
13	// queryExpansionPrompt instructs the agent to rewrite a task into retrieval
14	// terms. The measured gap is that a high-level request ("add a path subcommand")
15	// shares little vocabulary with the specific facts the work produced; expansion
16	// bridges it by naming the identifiers, components, and synonyms likely to
17	// appear in those facts. Like the other agent prompts it must not begin with a
18	// dash.
19	func queryExpansionPrompt() string {
20		return `You expand a software task into search terms for retrieving durable engineering
21	notes about that work. The query on stdin is a developer's request; the notes use
22	specific technical vocabulary the request may not.
23	
24	Output a single line: 6 to 15 space-separated terms — likely identifiers, package
25	and component names, synonyms, and key technical nouns that notes about this task
26	would contain. No prose, no punctuation beyond what a code identifier needs.`
27	}
28	
29	// parseExpansion takes the agent's expansion output and returns a bounded,
30	// single-line term string to append to the query.
31	func parseExpansion(output string) string {
32		for _, line := range strings.Split(output, "\n") {
33			line = strings.TrimSpace(line)
34			if line == "" || strings.HasPrefix(line, "#") {
35				continue
36			}
37			return base.TruncateString(strings.Join(strings.Fields(line), " "), 240)
38		}
39		return ""
40	}
41	
42	// expandQuery returns extra retrieval terms for a query, consulting the cache
43	// first so repeated evals are deterministic and cheap.
44	func expandQuery(ctx context.Context, run base.DistillAgentRunner, args []string, repoDir, query string, cache *expansionCache) (string, error) {
45		if v, ok := cache.get(query); ok {
46			return v, nil
47		}
48		out, err := run(ctx, repoDir, args, []byte(query), defaultDistillTimeout)
49		if err != nil {
50			return "", err
51		}
52		exp := parseExpansion(out)
53		cache.set(query, exp)
54		return exp, nil
55	}
56	
57	// expandedQuery is query plus its expansion terms; an empty expansion leaves the
58	// query unchanged.
59	func expandedQuery(query, expansion string) string {
60		if strings.TrimSpace(expansion) == "" {
61			return query
62		}
63		return query + " " + expansion
64	}
65	
66	// expansionCache persists query -> expansion terms so an expanded eval re-runs
67	// without re-calling the agent.
68	type expansionCache struct {
69		path  string
70		terms map[string]string
71		dirty bool
72	}
73	
74	func loadExpansionCache(path string) *expansionCache {
75		c := &expansionCache{path: path, terms: map[string]string{}}
76		if strings.TrimSpace(path) == "" {
77			return c
78		}
79		if data, err := os.ReadFile(path); err == nil {
80			if err := json.Unmarshal(data, &c.terms); err != nil || c.terms == nil {
81				c.terms = map[string]string{}
82			}
83		}
84		return c
85	}
86	
87	func (c *expansionCache) get(query string) (string, bool) {
88		if c == nil {
89			return "", false
90		}
91		v, ok := c.terms[query]
92		return v, ok
93	}
94	
95	func (c *expansionCache) set(query, expansion string) {
96		if c == nil {
97			return
98		}
99		c.terms[query] = expansion
100		c.dirty = true
101	}
102	
103	func (c *expansionCache) save() error {
104		if c == nil || !c.dirty || strings.TrimSpace(c.path) == "" {
105			return nil
106		}
107		data, err := json.MarshalIndent(c.terms, "", "  ")
108		if err != nil {
109			return err
110		}
111		return brainstore.WriteFileAtomic(c.path, append(data, '\n'), 0o600)
112	}
