17		"github.com/entireio/entire-brain/internal/cli/internal/base"
18		"github.com/entireio/entire-brain/internal/cli/internal/factstore"
19		bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"
20		"github.com/spf13/cobra"
21	)
22	
23	const (
24		verifySchemaVersion = 1
25	
26		verifyVerdictVerified           = "verified"
27		verifyVerdictStale              = "stale"
28		verifyVerdictOrphaned           = "orphaned"
29		verifyVerdictUnverifiableHere   = "unverifiable-here"
30		verifyTurnSigningLimitation     = "pending turn signing"
31		verifyCheckpointUnavailableHint = "local checkpoint refs unavailable"
32	)
33	
34	var (
35		errVerifyIssues       = errors.New("verification found stale or orphaned memories")
36		errVerifyStrictIssues = errors.New("verification found unverifiable-here memories")
37		// errVerifyStoreIncomplete is the verdict for a corpus that is short: the
38		// facts verify cannot read are neither verified nor orphaned, they are
39		// gone, and reporting them as "0 orphaned" was the defect.
40		errVerifyStoreIncomplete = errors.New("verification incomplete: the memory store cannot produce every memory the manifest declares")
41	)
42	
43	type verifyCommandOptions struct {
44		branch             string
45		limit              int
46		all                bool
47		json               bool
48		failOnUnverifiable bool
49		strict             bool // alias flag for failOnUnverifiable; OR'd in at run time
50		// sample verifies only the `limit` most recently updated facts in
51		// no-target mode. Full verification can shell out per distinct commit
52		// anchor, so status never invokes it; doctor and verify own that work.
53		sample bool
54	}
55	
56	type verifyReport struct {
57		SchemaVersion int                `json:"schema_version"`
58		GeneratedAt   time.Time          `json:"generated_at"`
59		Repo          brainStatusRepo    `json:"repo"`
60		BrainPath     string             `json:"brain_path"`
61		Branch        string             `json:"branch"`
62		Target        string             `json:"target,omitempty"`
63		Query         string             `json:"query,omitempty"`
64		Summary       verifySummary      `json:"summary"`
65		Results       []verifyFactResult `json:"results"`
66		Warnings      []string           `json:"warnings,omitempty"`
67		// StoreIntegrity is the manifest-vs-store cross-check. verify's whole job
68		// is fact integrity, and without this it answered "0 orphaned" about a
69		// store that had lost a fact — it verified the facts it could still read
70		// and never asked whether that was all of them. Present only when the
71		// cross-check fails.
