134	
135	func newVerifyCommand(opts Options) *cobra.Command {
136		verifyOpts := verifyCommandOptions{limit: 10}
137		cmd := &cobra.Command{
138			Use:   "verify [<memory-id | query>]",
139			Short: "Verify durable memory anchors against local retained sources",
140			Args:  cobra.MaximumNArgs(1),
141			RunE: func(cmd *cobra.Command, args []string) error {
142				target := ""
143				if len(args) == 1 {
144					target = args[0]
145				}
146				return runVerify(cmd.Context(), cmd, opts, verifyOpts, target)
147			},
148		}
149		cmd.Flags().StringVar(&verifyOpts.branch, "branch", "", "Branch to verify memories from (default: current branch)")
150		cmd.Flags().IntVar(&verifyOpts.limit, "limit", 10, "Maximum memories to verify for query mode")
151		cmd.Flags().BoolVar(&verifyOpts.all, "all", false, "Include superseded and retracted memories")
152		cmd.Flags().BoolVar(&verifyOpts.json, "json", false, "Emit machine-readable JSON")
153		cmd.Flags().BoolVar(&verifyOpts.strict, "strict", false, "Alias for --fail-on-unverifiable")
154		cmd.Flags().BoolVar(&verifyOpts.failOnUnverifiable, "fail-on-unverifiable", false, "Return nonzero when any matched memory is unverifiable-here (stale/orphaned always fail)")
155		return cmd
156	}
157	
158	func runVerify(ctx context.Context, cmd *cobra.Command, opts Options, verifyOpts verifyCommandOptions, target string) error {
159		if verifyOpts.limit <= 0 {
160			return fmt.Errorf("--limit must be greater than 0")
161		}
162		repoDir, brainDir, branch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), verifyOpts.branch)
163		if err != nil {
164			return err
165		}
166		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
167		if err != nil {
168			return err
169		}
170		report, err := buildVerifyReport(ctx, opts, repoDir, brainDir, storage.Key, branch, verifyOpts, target)
171		if err != nil {
172			return err
173		}
174		if verifyOpts.json {
175			if err := cmdutil.WriteJSON(cmd, report); err != nil {
176				return err
177			}
178		} else {
179			renderVerifyReportText(cmd, report)
180		}
181		if err := verifyFailureForReport(report, verifyOpts); err != nil {
182			return renderedCommandError{err: err}
183		}
184		return nil
185	}
186	
187	func verifyFailureForReport(report verifyReport, verifyOpts verifyCommandOptions) error {
188		// A store that cannot produce what the manifest declares fails verification
189		// unconditionally, and before the per-fact verdicts: those verdicts were
190		// computed over the survivors, so a clean sweep of them is not a pass. This
191		// matches how a corrupt history index behaves today — the read refuses and
192		// the command exits nonzero — rather than reporting success about a corpus
193		// it knows is short.
194		if report.StoreIntegrity != nil {
195			return errVerifyStoreIncomplete
196		}
197		if report.Summary.Stale > 0 || report.Summary.Orphaned > 0 {
198			return errVerifyIssues
199		}
200		if (verifyOpts.failOnUnverifiable || verifyOpts.strict) && report.Summary.UnverifiableHere > 0 {
201			return errVerifyStrictIssues
202		}
203		return nil
204	}
