206	func buildVerifyReport(ctx context.Context, opts Options, repoDir, brainDir, repoKey, branch string, verifyOpts verifyCommandOptions, target string) (verifyReport, error) {
207		manifest, err := bmanifest.Load(brainDir)
208		if err != nil {
209			return verifyReport{}, err
210		}
211		allFacts, err := factstore.Load(brainDir, branch)
212		if err != nil {
213			return verifyReport{}, err
214		}
215		// A fact the store can no longer produce is not "0 orphaned" — it is a
216		// fact that is gone, and verify is the command that must say so. Check the
217		// manifest's claim against the store before verifying what survived, so
218		// the verdict below can never be read as a clean bill of health for a
219		// corpus that is short.
220		var storeIntegrity *factstore.Integrity
221		if manifest != nil && manifest.Sources != nil {
222			if integrity := factstore.Inspect(brainDir, manifest.Sources.Facts); !integrity.OK() {
223				storeIntegrity = &integrity
224			}
225		}
226		selected, query, err := selectFactsForVerify(allFacts, target, verifyOpts)
227		if err != nil {
228			return verifyReport{}, err
229		}
230		vctx := &verifyContext{
231			ctx:      ctx,
232			opts:     opts,
233			repoDir:  repoDir,
234			brainDir: brainDir,
235			branch:   branch,
236			manifest: manifest,
237		}
238		report := verifyReport{
239			SchemaVersion:  verifySchemaVersion,
240			GeneratedAt:    opts.Now().UTC(),
241			Repo:           brainStatusRepo{Root: repoDir, Key: repoKey},
242			BrainPath:      brainDir,
243			Branch:         branch,
244			Target:         strings.TrimSpace(target),
245			Query:          query,
246			Results:        []verifyFactResult{},
247			StoreIntegrity: storeIntegrity,
248		}
249		for _, fact := range selected {
250			result := vctx.verifyFact(fact)
251			report.Results = append(report.Results, result)
252			addVerifyResultToSummary(&report.Summary, result)
253		}
254		if verifyOpts.sample && target == "" {
255			selectable := 0
256			for _, fact := range allFacts {
257				if verifyOpts.all || fact.Status == factStatusActive {
258					selectable++
259				}
260			}
261			if selectable > len(selected) {
262				report.Summary.SampledOf = selectable
263			}
264		}
265		report.Warnings = append(report.Warnings, vctx.snapshotWarnings...)
266		return report, nil
267	}
268	
269	func selectFactsForVerify(facts []factRecord, target string, opts verifyCommandOptions) ([]factRecord, string, error) {
270		target = strings.TrimSpace(target)
271		if strings.HasPrefix(target, "fact:") {
272			i := indexOfFact(facts, target)
273			if i < 0 {
274				return nil, "", fmt.Errorf("no memory %s", target)
275			}
276			return []factRecord{facts[i]}, "", nil
277		}
278		if target != "" {
279			return rankFacts(facts, target, opts.limit, opts.all), target, nil
280		}
281		selected := make([]factRecord, 0, len(facts))
282		for _, fact := range facts {
283			if opts.all || fact.Status == factStatusActive {
284				selected = append(selected, fact)
285			}
286		}
287		if opts.sample && opts.limit > 0 && len(selected) > opts.limit {
288			// Most recently updated first: the facts an agent is most likely to
289			// consume next are the most valuable ones to spot-check.
290			sort.SliceStable(selected, func(i, j int) bool { return selected[i].UpdatedAt.After(selected[j].UpdatedAt) })
291			selected = selected[:opts.limit]
292		}
293		return selected, "", nil
294	}
