296	func (v *verifyContext) verifyFact(fact factRecord) verifyFactResult {
297		result := verifyFactResult{
298			Fact:    fact,
299			Verdict: verifyVerdictVerified,
300			Reason:  "all locally checkable anchors resolved",
301			Anchors: []verifyAnchorResult{},
302			Limitations: []verifyLimitation{{
303				Scope:   "turn-signature",
304				Verdict: verifyVerdictUnverifiableHere,
305				Reason:  verifyTurnSigningLimitation,
306			}},
307		}
308		if len(fact.Provenance) == 0 {
309			result.Verdict = verifyVerdictUnverifiableHere
310			result.Reason = "memory has no retained source anchor"
311			return result
312		}
313		// NO RECORD-LEVEL ORIGIN GATE. Both of the ones that used to live here
314		// bailed for the WHOLE fact, which is the wrong granularity for a record
315		// that can hold anchors of both kinds.
316		//
317		// factmerge.Upsert keys on the content id, independent of Origin, and
318		// keeps the existing record's Origin while unioning anchors. So a fact can
319		// end up Origin "imported" holding BOTH its foreign anchor and a genuine
320		// local one (a later distill of colliding text), and bailing on the record
321		// meant that real commit, checkpoint and transcript were never checked at
322		// all. The mirror case -- an authored record that gains a foreign anchor --
323		// is what the per-anchor check in verifyAnchor was added for; this is the
324		// same bug on the other side of the same merge.
325		//
326		// Per-anchor handles every case, and better:
327		//   foreign-shaped anchor -> unverifiable-here, naming the tool
328		//   genuine local anchor  -> checked normally
329		//   repo-shaped anchor on an "imported" record -> CHECKED, so a fabricated
330		//     commit is reported missing rather than described as an origin
331		//     contradiction and left unexamined
332		//
333		// That last one is why nothing is lost by dropping the contradiction
334		// message: actually resolving the anchor is a stronger answer than
335		// declaring it inconsistent.
336		factBranch := fact.Branch
337		if factBranch == "" {
338			factBranch = v.branch
339		}
340		for _, anchor := range fact.Provenance {
341			anchorResult := v.verifyAnchor(anchor, factBranch)
342			result.Anchors = append(result.Anchors, anchorResult)
343			result.Verdict = worseVerifyVerdict(result.Verdict, anchorResult.Verdict)
344		}
345		// Prefer a SPECIFIC anchor reason over the generic one.
346		//
347		// reasonForFactVerdict describes a verdict, not a cause: "one or more
348		// anchors need finer local evidence" is true of an imported fact, a
349		// turn-signature limitation and a sparse authored anchor alike, and tells
350		// the reader none of them apart. When every anchor that produced this
351		// verdict gives the SAME reason, that reason is the fact's reason, and it
352		// is the one the reader can act on.
353		//
354		// Only when they agree. Two different causes collapsed into one sentence
355		// would be a worse answer than the generic line, not a better one.
356		if specific := sharedAnchorReason(result.Anchors, result.Verdict); specific != "" {
357			result.Reason = specific
358		} else {
359			result.Reason = reasonForFactVerdict(result.Verdict)
360		}
361		return result
362	}
363	
364	// sharedAnchorReason returns the one reason given by every anchor carrying the
365	// fact's verdict, or "" when they disagree or none is set.
366	func sharedAnchorReason(anchors []verifyAnchorResult, verdict string) string {
367		reason := ""
368		for _, anchor := range anchors {
369			if anchor.Verdict != verdict {
370				continue
371			}
372			switch {
373			case strings.TrimSpace(anchor.Reason) == "":
374				return ""
375			case reason == "":
376				reason = anchor.Reason
377			case reason != anchor.Reason:
378				return ""
379			}
380		}
381		return reason
382	}
383	
384	func (v *verifyContext) verifyAnchor(anchor factAnchor, factBranch string) verifyAnchorResult {
385		result := verifyAnchorResult{Anchor: anchor, Verdict: verifyVerdictVerified, Reason: "anchor resolved locally", Checks: []verifyCheck{}}
386	
387		// PER-ANCHOR, because the record-level origin gates above are not enough.
388		//
389		// factmerge.Upsert keys on the content-addressed id and keeps the EXISTING
390		// record's Origin while unioning provenance. So an imported memory whose
391		// text and paths normalise onto a pre-existing authored fact -- which
392		// importing under an existing taxonomy prefix explicitly permits -- yields
393		// a fact with Origin != "imported" that nonetheless carries a foreign
394		// anchor. Neither origin gate fires, and this function then tries to
395		// resolve "mem0:abc" as a local session and reports the fact ORPHANED:
396		// "its evidence is gone", when its evidence was never here. That is the
397		// same false and alarming diagnosis the origin gates exist to prevent,
398		// reached by a different route.
399		//
400		// Per-anchor is also the correct granularity for that record: it holds the
401		// original local anchor AND the foreign one, so the local one must still be
402		// checked normally while the foreign one must not be called orphaned.
403		// worseVerifyVerdict then aggregates, and unverifiable-here does not mask a
404		// genuine local failure.
405		if anchorNamesAForeignSource(anchor) {
406			result.Verdict = verifyVerdictUnverifiableHere
407			result.Reason = "anchor names a session in " + strings.SplitN(strings.TrimSpace(anchor.SessionID), ":", 2)[0] + ", not this repository"
408			result.addCheck(verifyCheck{Name: "foreign_source", Verdict: verifyVerdictUnverifiableHere, Reason: result.Reason})
409			return result
410		}
411		hasRetainedSource := strings.TrimSpace(anchor.SessionID) != "" ||
412			strings.TrimSpace(anchor.CheckpointID) != "" ||
413			strings.TrimSpace(anchor.Transcript) != "" ||
414			anchor.Line > 0
415	
416		if strings.TrimSpace(anchor.Commit) != "" {
417			result.addCheck(v.verifyCommit(anchor.Commit))
418		}
419	
420		if !hasRetainedSource {
421			if result.Verdict == verifyVerdictOrphaned {
422				result.Reason = "commit anchor is missing locally"
423				return result
424			}
425			result.addCheck(verifyCheck{Name: "retained_source", Verdict: verifyVerdictUnverifiableHere, Reason: "authored memory has no retained source anchor"})
426			result.Reason = "authored memory has no retained source anchor"
427			return result
428		}
429	
430		session, sessionFound, sessionCheck := v.verifyExportedSession(anchor, factBranch)
431		result.addCheck(sessionCheck)
432		if !sessionFound {
433			result.Reason = sessionCheck.Reason
434			return result
435		}
436		if strings.TrimSpace(anchor.TurnID) != "" {
437			result.addCheck(verifyTurnID(session, anchor.TurnID))
438		}
439		if strings.TrimSpace(anchor.CheckpointID) != "" {
440			result.addCheck(v.verifyCheckpoint(anchor.CheckpointID))
441		}
442	
443		transcriptRel := strings.TrimSpace(anchor.Transcript)
444		if transcriptRel == "" {
445			transcriptRel = session.TranscriptPath
446		}
447		transcriptContent := ""
448		transcriptRead := false
449		if transcriptRel == "" {
450			result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictOrphaned, Reason: "anchor has no transcript path"})
451		} else {
452			if session.TranscriptPath != "" && anchor.Transcript != "" && filepath.ToSlash(session.TranscriptPath) != filepath.ToSlash(anchor.Transcript) {
453				result.addCheck(verifyCheck{Name: "transcript_path", Verdict: verifyVerdictStale, Reason: fmt.Sprintf("exported session now points at %s", session.TranscriptPath)})
454			}
455			data, err := readCanonicalHistoryTranscript(v.ctx, v.brainDir, transcriptRel)
456			if err != nil {
457				result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictOrphaned, Reason: err.Error()})
458			} else {
459				transcriptContent = string(data)
460				transcriptRead = true
461				result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictVerified, Reason: transcriptRel})
462			}
463		}
464		if anchor.Line > 0 && transcriptRead {
465			line, ok := transcriptLine(transcriptContent, anchor.Line)
466			if !ok {
467				result.addCheck(verifyCheck{Name: "line", Verdict: verifyVerdictOrphaned, Reason: fmt.Sprintf("line %d is outside transcript", anchor.Line)})
468			} else {
469				result.LineExcerpt = base.TruncateString(strings.Join(strings.Fields(line), " "), 200)
470				result.addCheck(verifyCheck{Name: "line", Verdict: verifyVerdictVerified, Reason: fmt.Sprintf("line %d resolved", anchor.Line)})
471			}
472		}
473		if strings.TrimSpace(anchor.CheckpointID) != "" && transcriptRead {
474			result.addCheck(v.verifyCheckpointTranscript(anchor, session, transcriptContent))
475		}
476		result.Reason = reasonForAnchorVerdict(result.Verdict)
477		return result
478	}
