480	func (r *verifyAnchorResult) addCheck(check verifyCheck) {
481		if check.Name == "" {
482			return
483		}
484		r.Checks = append(r.Checks, check)
485		r.Verdict = worseVerifyVerdict(r.Verdict, check.Verdict)
486	}
