488	func (v *verifyContext) verifyCommit(commit string) verifyCheck {
489		commit = strings.TrimSpace(commit)
490		if commit == "" {
491			return verifyCheck{}
492		}
493		// Anchors are data: a crafted "commit" like --upload-pack=... must never
494		// reach git argv. Hex object ids only, matching the repo's hardening.
495		if !verifyCommitIDPattern.MatchString(commit) {
496			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "anchor commit is not a valid commit id"}
497		}
498		if cached, ok := v.commitChecks[commit]; ok {
499			return cached
500		}
501		check := v.verifyCommitUncached(commit)
502		if v.commitChecks == nil {
503			v.commitChecks = map[string]verifyCheck{}
504		}
505		v.commitChecks[commit] = check
506		return check
507	}
508	
509	var verifyCommitIDPattern = regexp.MustCompile(`^[0-9a-fA-F]{4,64}$`)
510	
511	func (v *verifyContext) verifyCommitUncached(commit string) verifyCheck {
512		// Verification is defined over locally retained evidence. Both existence
513		// and reachability can traverse promisor objects, so guard every Git object
514		// read against lazy network fetches just like checkpoint transcript reads.
515		if _, _, err := runCheckpointGitWithPolicy(v.ctx, v.opts.Runner, v.repoDir, true, "cat-file", "-e", commit+"^{commit}"); err != nil {
516			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "commit is missing locally"}
517		}
518		stdout, _, err := runCheckpointGitWithPolicy(v.ctx, v.opts.Runner, v.repoDir, true, "for-each-ref", "--format=%(refname)", "--contains", commit, "refs/heads", "refs/remotes", "refs/tags")
519		if err != nil {
520			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "commit reachability could not be checked locally"}
521		}
522		if strings.TrimSpace(string(stdout)) == "" {
523			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "commit is not reachable from local refs"}
524		}
525		return verifyCheck{Name: "commit", Verdict: verifyVerdictVerified, Reason: "commit exists and is reachable from local refs"}
526	}
527	
528	func (v *verifyContext) verifyExportedSession(anchor factAnchor, factBranch string) (exportSession, bool, verifyCheck) {
529		sessionID := strings.TrimSpace(anchor.SessionID)
530		if sessionID == "" {
531			return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: "anchor has no session_id"}
532		}
533		if v.manifest == nil || v.manifest.Sources == nil || v.manifest.Sources.Sessions == nil {
534			return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: "exported sessions source is missing"}
535		}
536		var bySession []exportSession
537		for _, session := range v.manifest.Sources.Sessions.Sessions {
538			if session.SessionID != sessionID {
539				continue
540			}
541			if factBranch != "" && resolveDistillBranch(v.manifest, session) != factBranch {
542				continue
543			}
544			bySession = append(bySession, session)
545		}
546		if len(bySession) > 0 {
547			// One session id can span SEVERAL exported rows — the same session
548			// exported on more than one branch — and a fact with no branch of its own
549			// keeps all of them. Which row is returned decides the transcript and the
550			// turn id every later check reads, so it may never be "whichever the
551			// manifest listed first".
552			if anchor.CheckpointID == "" {
553				return pickExportedSession(v.manifest, bySession), true, verifyCheck{Name: "session", Verdict: verifyVerdictVerified, Reason: "session is present in exported sessions"}
554			}
555			if row, ok := exportedSessionAtCheckpoint(v.manifest, bySession, anchor.CheckpointID); ok {
556				return row, true, verifyCheck{Name: "session", Verdict: verifyVerdictVerified, Reason: "session is present in exported sessions"}
557			}
558			// The anchor names a checkpoint that is not the session's latest. That
559			// is not automatically staleness: provenance sharpening deliberately
560			// anchors a fact to the checkpoint that actually changed the entity,
561			// which is usually mid-session. It is only stale if the checkpoint does
562			// not belong to this session at all.
563			//
564			// Verifying it requires knowing WHICH row owns it. With several rows and
565			// no way to tell them apart, the honest answer is the pre-sharpening one
566			// — stale — rather than an arbitrary row promoted to verified.
567			if member, owned := v.sessionCheckpoint(sessionID, anchor.CheckpointID); owned {
568				if row, ok := exportedSessionOwning(v.manifest, bySession, member); ok {
569					return row, true, verifyCheck{
570						Name:    "session",
571						Verdict: verifyVerdictVerified,
572						Reason:  fmt.Sprintf("session is present in exported sessions; anchor names its checkpoint %s", anchor.CheckpointID),
573					}
574				}
575			}
576			row := pickExportedSession(v.manifest, bySession)
577			return row, true, verifyCheck{Name: "session", Verdict: verifyVerdictStale, Reason: fmt.Sprintf("session is now exported at checkpoint %s", row.LatestCheckpoint)}
578		}
579		if factBranch != "" {
580			return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: fmt.Sprintf("session is missing from exported sessions on branch %s", factBranch)}
581		}
582		return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: "session is missing from exported sessions"}
583	}
584	
585	// exportedSessionAtCheckpoint returns the row whose LATEST checkpoint is the
586	// anchored one — the exact match, and the only one that needs no local
587	// checkpoint store to justify it. Several rows sharing that checkpoint fall
588	// back to the deterministic pick.
589	func exportedSessionAtCheckpoint(manifest *exportManifest, rows []exportSession, checkpointID string) (exportSession, bool) {
590		var matches []exportSession
591		for _, row := range rows {
592			if row.LatestCheckpoint == checkpointID {
593				matches = append(matches, row)
594			}
595		}
596		if len(matches) == 0 {
597			return exportSession{}, false
598		}
599		return pickExportedSession(manifest, matches), true
600	}
601	
602	// exportedSessionOwning returns the exported row a local (session, checkpoint)
603	// membership record belongs to, and ok=false when that cannot be decided. The
604	// membership record names the branch the checkpoint was made on, which is
605	// exactly what distinguishes one row of a multi-branch session from another; if
606	// it does not name one, or names one that does not select a single row, the
607	// caller keeps the conservative verdict instead of guessing.
608	func exportedSessionOwning(manifest *exportManifest, rows []exportSession, member sessionCheckpoint) (exportSession, bool) {
609		if len(rows) == 1 {
610			return rows[0], true
611		}
612		branch := strings.TrimSpace(member.Branch)
613		if branch == "" {
614			return exportSession{}, false
615		}
616		var matches []exportSession
617		for _, row := range rows {
618			if resolveDistillBranch(manifest, row) == branch {
619				matches = append(matches, row)
620			}
621		}
622		if len(matches) != 1 {
623			return exportSession{}, false
624		}
625		return matches[0], true
626	}
627	
628	// pickExportedSession chooses one of several rows the manifest lists for the
629	// same session id. Any total order over the rows' own contents will do; what
630	// matters is that it is not the manifest's array order, which is an artifact of
631	// how the export happened to be assembled.
632	func pickExportedSession(manifest *exportManifest, rows []exportSession) exportSession {
633		best := rows[0]
634		bestKey := exportedSessionKey(manifest, best)
635		for _, row := range rows[1:] {
636			if key := exportedSessionKey(manifest, row); key < bestKey {
637				best, bestKey = row, key
638			}
639		}
640		return best
641	}
642	
643	func exportedSessionKey(manifest *exportManifest, row exportSession) string {
644		return strings.Join([]string{
645			resolveDistillBranch(manifest, row),
646			row.LatestCheckpoint,
647			strconv.Itoa(row.SessionIndex),
648			row.TranscriptPath,
649			row.TurnID,
650		}, "\x00")
651	}
652	
653	func verifyTurnID(session exportSession, turnID string) verifyCheck {
654		if session.TurnID == "" {
655			return verifyCheck{Name: "turn", Verdict: verifyVerdictUnverifiableHere, Reason: "exported session has no turn_id; pending turn signing"}
656		}
657		if session.TurnID != turnID {
658			return verifyCheck{Name: "turn", Verdict: verifyVerdictStale, Reason: fmt.Sprintf("exported session now points at turn %s", session.TurnID)}
659		}
660		return verifyCheck{Name: "turn", Verdict: verifyVerdictVerified, Reason: "turn_id is present in exported session metadata"}
661	}
662	
663	func (v *verifyContext) verifyCheckpoint(checkpointID string) verifyCheck {
664		snapshot, err := v.localCheckpointSnapshot()
665		if err != nil {
666			return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictUnverifiableHere, Reason: verifyCheckpointUnavailableHint + ": " + err.Error()}
667		}
668		if checkpointUnreadableInSnapshot(snapshot, checkpointID) {
669			return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictUnverifiableHere, Reason: "checkpoint was listed locally but its retained source is unreadable"}
670		}
671		if !checkpointExistsInSnapshot(snapshot, checkpointID) {
672			return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictOrphaned, Reason: "checkpoint is missing from local checkpoint refs"}
673		}
674		return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictVerified, Reason: "checkpoint exists in local checkpoint refs"}
675	}
676	
677	func (v *verifyContext) verifyCheckpointTranscript(anchor factAnchor, session exportSession, exportedTranscript string) verifyCheck {
678		snapshot, err := v.localCheckpointSnapshot()
679		if err != nil {
680			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictUnverifiableHere, Reason: verifyCheckpointUnavailableHint + ": " + err.Error()}
681		}
682		if checkpointUnreadableInSnapshot(snapshot, anchor.CheckpointID) {
683			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictUnverifiableHere, Reason: "checkpoint was listed locally but its retained transcript source is unreadable"}
684		}
685		sourcePath, sourceKey := v.snapshotSourceTranscriptPath(snapshot, anchor, session)
686		if sourcePath == "" {
687			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictOrphaned, Reason: "checkpoint transcript path is missing"}
688		}
689		transcript, err := readSnapshotTranscriptFromSource(v.ctx, v.opts.Runner, snapshot, sourceKey, sourcePath)
690		if err != nil {
691			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictOrphaned, Reason: err.Error()}
692		}
693		if bytes.Equal(transcript, []byte(exportedTranscript)) {
694			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictVerified, Reason: "exported transcript matches local checkpoint transcript"}
695		}
696		// The export carries the session's transcript at its LATEST checkpoint. A
697		// sharpened anchor points at an earlier checkpoint of the same session,
698		// whose transcript is that same session earlier in time — a prefix, because
699		// a session's transcript only ever grows. Equality is still required for an
700		// anchor on the latest checkpoint, so nothing about the original check is
701		// relaxed; this only covers the earlier-checkpoint case the sharpener
702		// introduced.
703		if session.LatestCheckpoint != "" && anchor.CheckpointID != session.LatestCheckpoint &&
704			len(transcript) > 0 && bytes.HasPrefix([]byte(exportedTranscript), transcript) {
705			return verifyCheck{
706				Name:    "checkpoint_transcript",
707				Verdict: verifyVerdictVerified,
708				Reason:  fmt.Sprintf("local checkpoint %s transcript is a prefix of the exported session transcript", anchor.CheckpointID),
709			}
710		}
711		return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictStale, Reason: "exported transcript differs from local checkpoint transcript"}
712	}
