753		for _, candidate := range snapshot.Selected {
754			if candidate.SessionID == anchor.SessionID && candidate.CheckpointID == anchor.CheckpointID && candidate.SourceTranscriptPath != "" {
755				return candidate.SourceTranscriptPath, candidate.SourceKey
756			}
757		}
758		// Selected holds only each session's newest checkpoint. A sharpened anchor
759		// names an earlier one, whose transcript lives at ITS own path under ITS own
760		// session index — deriving the path from the exported (latest) session's
761		// index would read the wrong blob, or none.
762		for _, member := range snapshot.SessionCheckpoints {
