764				return member.TranscriptPath, member.SourceKey
765			}
766		}
767		path := snapshotTranscriptPath(anchor.CheckpointID, session.SessionIndex, snapshot.TranscriptFileName)
768		for sourceKey, source := range snapshot.Sources {
769			if hasSnapshotTranscript(path, source.TreePaths) {
770				return path, sourceKey
771			}
772		}
773		if hasSnapshotTranscript(path, snapshot.TreePaths) {
774			return path, ""
775		}
776		rootPath := snapshotRootTranscriptPath(anchor.CheckpointID, snapshot.TranscriptFileName)
777		for sourceKey, source := range snapshot.Sources {
778			if hasSnapshotTranscript(rootPath, source.TreePaths) {
779				return rootPath, sourceKey
780			}
781		}
782		if hasSnapshotTranscript(rootPath, snapshot.TreePaths) {
783			return rootPath, ""
