790	// snapshot never touches the network. Discovery completeness is the caller's
791	// problem — a reader resolves checkpoints it already knows by id.
792	func loadLocalCheckpointSnapshotLocalOnly(ctx context.Context, runner CommandRunner, repoDir string, raw bool, branchDestinations checkpointBranchDestinations, cache *checkpointMetadataCache) (*checkpointSnapshot, []string, error) {
793		settings, settingsErr := readEntireSettings(repoDir)
794		primary, configured, primaryErr := configuredCheckpointPrimary(repoDir, settings)
