171	func treeContentHash(t *testing.T, root string) string {
172		t.Helper()
173		var paths []string
174		if err := filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
175			if err != nil {
176				return err
177			}
178			if !entry.IsDir() {
179				rel, _ := filepath.Rel(root, path)
180				rel = filepath.ToSlash(rel)
181				vitalityLock := filepath.ToSlash(filepath.Join(brainstore.BrainLockDirName, factsVitalityLockName))
182				if filepath.Base(path) == factsVitalityLogFileName ||
183					filepath.Base(path) == factsVitalityRollupFileName ||
184					rel == vitalityLock ||
185					// The owner sidecar is part of the same artifact as the lock
186					// above and is rewritten on the same acquisitions. It carries
187					// the timestamp that used to live INSIDE the lock file, so
188					// excluding the lock without its sidecar would make this hash
189					// sensitive to the clock rather than to the brain.
190					rel == vitalityLock+brainstore.FileLockOwnerSuffix {
191					return nil
192				}
193				paths = append(paths, path)
194			}
195			return nil
196		}); err != nil {
197			t.Fatal(err)
198		}
199		sort.Strings(paths)
200		h := sha256.New()
201		for _, path := range paths {
202			data, err := os.ReadFile(path)
203			if err != nil {
204				t.Fatal(err)
205			}
206			rel, _ := filepath.Rel(root, path)
207			_, _ = h.Write([]byte(rel))
208			_, _ = h.Write(data)
209		}
210		return hex.EncodeToString(h.Sum(nil))
211	}
